const talentRespecs = `-- name: TalentRespecs :one
SELECT count(*) FILTER (WHERE talent_respecs > 0)::bigint AS lords,
       coalesce(sum(talent_respecs), 0)::bigint           AS respecs
FROM app.players
`

type TalentRespecsRow struct {
	Lords   int64
	Respecs int64
}

// And how often it changes its mind.
func (q *Queries) TalentRespecs(ctx context.Context) (TalentRespecsRow, error) {
	row := q.db.QueryRow(ctx, talentRespecs)
	var i TalentRespecsRow
	err := row.Scan(&i.Lords, &i.Respecs)
	return i, err
}

const talentsPicked = `-- name: TalentsPicked :many
SELECT talent_id,
       count(*)::bigint                AS lords,
       coalesce(sum(ranks), 0)::bigint AS ranks
FROM app.player_talents
GROUP BY talent_id
ORDER BY sum(ranks) DESC
LIMIT $1
`

type TalentsPickedRow struct {
	TalentID string
	Lords    int64
	Ranks    int64
}

// The tree: which ranks the realm is buying.
func (q *Queries) TalentsPicked(ctx context.Context, lim int32) ([]TalentsPickedRow, error) {
	rows, err := q.db.Query(ctx, talentsPicked, lim)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []TalentsPickedRow{}
	for rows.Next() {
		var i TalentsPickedRow
		if err := rows.Scan(&i.TalentID, &i.Lords, &i.Ranks); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
